/**
 * Kroje wbudowane w plik. Garamond do tekstu, Cormorant do tytułów — obcięte
 * do znaków, których gra faktycznie używa, więc całość waży kilkanaście kilobajtów
 * i działa też wtedy, gdy stronę otwiera się z dysku, bez sieci.
 */
const TEKST = 'data:font/woff2;base64,';
const KURSYWA = 'data:font/woff2;base64,';
const TYTUL = 'data:font/woff2;base64,';

export const KROJ = '"Trzewia Tekst", "EB Garamond", "Palatino Linotype", Palatino, Georgia, serif';
export const KROJ_TYTUL = '"Trzewia Tytul", "Cormorant Garamond", "Iowan Old Style", Georgia, serif';

let zaladowane = false;

export function zaladujKroje(): Promise<void> {
  if (zaladowane) return Promise.resolve();
  zaladowane = true;
  const style = document.createElement('style');
  style.textContent = `
@font-face { font-family: 'Trzewia Tekst'; src: url({TEKST}) format('woff2'); font-weight: 400; font-style: normal; font-display: block; }
@font-face { font-family: 'Trzewia Tekst'; src: url({KURSYWA}) format('woff2'); font-weight: 400; font-style: italic; font-display: block; }
@font-face { font-family: 'Trzewia Tytul'; src: url({TYTUL}) format('woff2'); font-weight: 600; font-style: normal; font-display: block; }
`.replace('{TEKST}', TEKST).replace('{KURSYWA}', KURSYWA).replace('{TYTUL}', TYTUL);
  document.head.appendChild(style);
  const czcionki = (document as any).fonts;
  if (!czcionki) return Promise.resolve();
  return Promise.all([
    czcionki.load('16px "Trzewia Tekst"'),
    czcionki.load('italic 16px "Trzewia Tekst"'),
    czcionki.load('600 32px "Trzewia Tytul"'),
  ]).then(() => undefined).catch(() => undefined);
}
